sub actor_display {
	my ($self, $args) = @_;
	return unless changeToInGameState();
	my ($actor, $mustAdd);

	#### Initialize ####

	my $nameID = unpack("V", $args->{ID});
	my $name = bytesToString($args->{name});
	$name =~ s/^\s+|\s+$//g;

	if ($args->{switch} eq "0086") {
