		$item_info = {
			len => 26,
			types => 'a2 v C2 v2 C2 a8 l v',
			keys => [qw(ID nameID type identified type_equip equipped broken upgrade cards expire bindOnEquipType)],
		};

		if (exists $args->{robe}) {  # PACKETVER >= 20100629
