	my $headerlen = 22;
	my $achieve_pack = 'V C V10 V C';
	my $achieve_len = length pack $achieve_pack;

	for (my $i = $headerlen; $i < $args->{RAW_MSG_SIZE}; $i+=$achieve_len) {
		my $achieve;

		($achieve->{achievementID},
		$achieve->{completed},
